#!/usr/bin/env bash
# Only use trusted archives generated by this project's backup.sh.
set -euo pipefail
cd "$(dirname "$0")/.."
source deploy/common.sh
[ $# = 1 ] || { echo "用法：bash deploy/rollback.sh backups/errorset-xxx.tar.gz" >&2; exit 1; }
[ -z "$(git status --porcelain --untracked-files=no)" ] || { echo "请先处理已跟踪文件的本地改动" >&2; exit 1; }
ARCHIVE="$(realpath "$1")"
STAGE="$(mktemp -d)"
trap 'rm -rf "$STAGE"' EXIT
tar xzf "$ARCHIVE" -C "$STAGE"
[ -d "$STAGE/data" ] && [ -f "$STAGE/.env" ] && [ -f "$STAGE/deployment-revision.txt" ] || { echo "备份不完整或不含代码版本" >&2; exit 1; }
REVISION="$(cat "$STAGE/deployment-revision.txt")"
[[ "$REVISION" =~ ^[0-9a-f]{40,64}$ ]] || exit 1
git cat-file -e "$REVISION^{commit}"
bash deploy/backup.sh
compose down
git checkout --detach "$REVISION"
PRESERVED="backups/pre-rollback-$(date +%Y%m%d-%H%M%S)-$$"
umask 077
mkdir -p "$PRESERVED"
$SUDO mv data "$PRESERVED/data"
cp .env "$PRESERVED/.env"
$SUDO cp -a "$STAGE/data" ./data
cp "$STAGE/.env" .env
bash deploy/setup_server.sh
echo "回滚完成：$REVISION；后续更新前需切回部署分支。"
